import{_ as r,l as o,o as e,c as n,v as t,p as s,x as l,d as i,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Delta / Gamma / Vega 对冲","description":"","frontmatter":{"title":"Delta / Gamma / Vega 对冲","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/greeks-hedge.md","filePath":"quant/greeks-hedge.md","lastUpdated":1789023840000}'),p={name:"quant/greeks-hedge.md"};function g(c,a,u,D,V,E){const m=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="delta-gamma-vega-对冲" tabindex="-1">Delta / Gamma / Vega 对冲 <a class="header-anchor" href="#delta-gamma-vega-对冲" aria-label="Permalink to &quot;Delta / Gamma / Vega 对冲&quot;">​</a></h1><div class="epigraph"><p>期权价值对标的、对标的的二阶、对波动率的一阶，构成日常风险账；对冲是用可交易工具把这几项暴露压到限额以内，而不是消灭全部 P&amp;L。</p><footer>—— Hull, Options, Futures, and Other Derivatives</footer></div><p>Black–Scholes–Merton 的复制论证在连续交易、常数波动、无跳跃时，用标的（或期货）动态对冲即可复制欧式期权。交易台并不活在定理里：仓位是一篮子香草与奇异，波动率在动，再平衡是离散的。John Hull 的教科书把希腊字母组织成可运算的风险：Delta 是对现货（或远期）的一阶，Gamma 是 Delta 对现货的导数，Vega 是对隐含波动率的一阶，再加上 Theta、Rho。对冲的意思是：选期货、掉期或别的期权，使组合的 \\(\\Delta,\\Gamma,\\nu\\) 落在限额内，并承认未对冲的高阶与交叉项会变成 P&amp;L。它与 <a href="/quant/discrete-hedge-error">离散对冲误差</a> 衔接：即使 Delta 在每次再平衡时都归零，Gamma 仍在两次平衡之间工作。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>非线性衍生产品的价值 \\(V(S,\\sigma,t)\\) 在市场因子变动时不是直线。一阶 Taylor 用 Delta 与 Vega 解释小移动；现货大动时 Gamma 与 Volga、Vanna 变成主导。若只对冲 Delta，等价于局部线性化，暴跌或暴涨时复制失败，而这正是卖出期权的风险。若要对冲 Gamma，必须引入另一个非线性工具——通常是别的期权——因为期货的 Gamma 为零。若要对冲 Vega，同样需要期权或方差互换一类对波动率敏感的工具。问题是在流动性、买卖价差与模型定义下，选哪几个工具、在哪一个微笑动态下算这些导数。</p><p>希腊字母依赖模型与报价惯例。Black 的 \\(\\Delta\\) 与「微笑 sticky strike」下的 \\(\\Delta\\) 不同；Heston 的 Vega 是对 \\(v_0\\) 或对某一参数，与对 Black 隐含波动的 Vega 要换算。Hull 的教学默认 Black–Scholes 公式的解析希腊字母，作为共同语言；生产上必须声明：对冲用的是哪一个曲面、哪一种 sticky 假设。</p><h3 id="三个一阶对象不是三种独立货币" tabindex="-1">三个一阶对象不是三种独立货币 <a class="header-anchor" href="#三个一阶对象不是三种独立货币" aria-label="Permalink to &quot;三个一阶对象不是三种独立货币&quot;">​</a></h3><p>Delta 改变时，若现货同时动、波动率也动，P&amp;L 不能拆成三个独立账户后简单相加——还有 \\(S\\) 与 \\(\\sigma\\) 的交叉 Vanna。把账分成 Delta 账、Gamma 账、Vega 账是管理近似：限额按线性风险加一点凸性缓冲。真正的复制误差见离散对冲与跳跃。方差互换对 Vega 几乎线性、对现货 Delta 在复制后较小，常被用来卸指数 Vega；单名则往往仍用香草。</p><p><span class="marginnote">市场说的 Vega 常是「隐含波动率变动一个百分点」的价值，不是对 Heston \\(\\sigma\\) 或 SABR \\(\\nu\\) 的偏导。报告希腊字母必须带单位：每 1% vol、每 1 个现货点、还是每 1 个远期基点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Black–Scholes 下欧式看涨</p> \\[\\Delta = \\mathrm{e}^{-qT}N(d_1),\\qquad \\Gamma=\\frac{\\mathrm{e}^{-qT}n(d_1)}{S\\sigma\\sqrt{T}},\\qquad \\nu=S\\mathrm{e}^{-qT}n(d_1)\\sqrt{T}, \\]<p>Vega 这里用 \\(\\nu\\) 以免与方差混淆。Delta 对冲：用 \\(-\\Delta\\) 单位标的（或等价期货）使组合 \\(\\Delta_{\\mathrm{port}}=0\\)。现货变动 \\(\\mathrm{d}S\\) 后，未再平衡前组合 P&amp;L 约 \\(\\frac12\\Gamma(\\mathrm{d}S)^2+\\Theta\\mathrm{d}t+\\nu\\mathrm{d}\\sigma+\\cdots\\)。卖出期权则 \\(\\Gamma\\lt 0\\)，需要在大动时亏损，用 Theta 收取时间价值作为补偿——这是 Hull 反复强调的 Gamma–Theta 权衡。</p><p>Gamma 对冲：加入数量 \\(\\lambda\\) 的对冲期权，使 \\(\\Gamma+\\lambda\\Gamma_h=0\\)，再回头调整标的使 Delta 仍为零。对冲期权会带来自己的 Vega 与期限结构，通常无法同时把 \\(\\Gamma\\) 与 \\(\\nu\\) 都精确打到零，除非工具足够多。实务是解一个小的加权最小二乘：对关键执行价、关键到期的桶做 Vega 与 Gamma 分桶，而不是对整个曲面的单一 Vega 标量。</p><h3 id="vega-分桶与微笑对冲" tabindex="-1">Vega 分桶与微笑对冲 <a class="header-anchor" href="#vega-分桶与微笑对冲" aria-label="Permalink to &quot;Vega 分桶与微笑对冲&quot;">​</a></h3><p>单一 Vega 把所有执行价的隐含波动当成平行移动。真实移动是倾斜与弯曲，对应 <a href="/quant/sabr">SABR</a> 的 \\(\\rho,\\nu\\) 或主元。分桶 Vega：按到期（有时再按 Delta）分组，用该桶里的香草去对冲该桶暴露。方差互换或 VIX 期货接近对 \\(1/K^2\\) 加权的方差敏感，和 ATM Vega 不同，见 <a href="/quant/variance-swap-vix">方差互换与 VIX</a>。外汇的 RR 与 BF 报价直接对应偏斜与弯曲的对冲工具，比单一 Vega 更接近市场坐标。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Delta 对冲把一阶现货风险转给期货市场，留下凸性。若隐含波动不变且再平衡连续，Gamma 与 Theta 在 Black–Scholes 方程里对消，复制误差趋于零。波动率一变，Vega 项出现，必须用别的期权再对冲；对冲期权的 Delta 又破坏原来的 Delta 中性，需要一轮迭代。这是交易日盘中的标准循环，不是模型缺陷。</p><p>对冲比率对微笑动态敏感。Sticky strike：执行价固定的隐含波动不随现货动，Delta 接近 Black Delta。Sticky delta：固定 Delta 的点跟着现货走。SABR 或局部波动率给出第三种。同一香草，三种 Delta 可以差几个百分点，对大名义这就是真实金钱。Hagan 等人写 SABR 的动机之一，正是让 Delta 与微笑移动一致，见 <a href="/quant/sabr">SABR</a>。Heston 下应对状态变量 \\(v\\) 做 Vega，再映射到市场报价的桶。</p><h3 id="gamma-的符号与尾部" tabindex="-1">Gamma 的符号与尾部 <a class="header-anchor" href="#gamma-的符号与尾部" aria-label="Permalink to &quot;Gamma 的符号与尾部&quot;">​</a></h3><p>做空香草：负 Gamma，现货静止时赚 Theta，大动时亏。做多香草相反。对冲 Gamma 并不是道德上「更中性」，只是把尾部卖给另一张期权的卖方。若对冲工具流动性差，名义 Gamma 对冲会在压力期转不动，账面中性瞬间变成裸露。限额因此同时约束 Gamma 与再对冲所需的流动性，而不是只约束瞬时 \\(\\Gamma\\) 数字。</p><p><span class="marginnote">Rho 与股息风险在长期限股权与可转债上可以大过日内 Delta。Hull 把 Rho 列为标准希腊字母，短到期外汇里它常被折进远期点，不单独对冲。</span></p>',22)),(e(),s(d,null,{default:l(()=>[h(m,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20Book%5B%22%E6%9C%9F%E6%9D%83%E8%B4%A6%E6%9C%AC%20V%22%5D%20--%3E%20D%5B%22Delta%20%E7%94%A8%E6%9C%9F%E8%B4%A7%E5%AF%B9%E5%86%B2%22%5D%0A%20%20Book%20--%3E%20G%5B%22Gamma%20%E7%94%A8%E5%8F%A6%E4%B8%80%E6%9C%9F%E6%9D%83%E5%AF%B9%E5%86%B2%22%5D%0A%20%20Book%20--%3E%20V%5B%22Vega%20%E5%88%86%E6%A1%B6%E7%94%A8%E9%A6%99%E8%8D%89%E6%88%96%E6%96%B9%E5%B7%AE%E4%BA%92%E6%8D%A2%22%5D%0A%20%20G%20--%3E%20D%0A%20%20V%20--%3E%20D%0A%20%20D%20--%3E%20Pnl%5B%22%E5%89%A9%E4%BD%99%3A%20%E9%AB%98%E9%98%B6%20%2F%20%E8%B7%B3%E8%B7%83%20%2F%20%E7%A6%BB%E6%95%A3%E8%AF%AF%E5%B7%AE%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>解析希腊字母假设模型正确、参数瞬时不变。跳风险不能用 Delta–Gamma 局部展开抓住；离散对冲留下与 \\(\\Gamma\\) 成正比的误差。多曲线下利率产品的「Delta」可能是对折现曲线、对投影曲线、对关键期限的不同桶，见 <a href="/quant/key-rate-duration">关键利率久期</a> 与 <a href="/quant/multi-curve-ois">OIS 与多曲线</a>。信用与借券不在 Black–Scholes 希腊字母里。</p><p>Hull 提供的是共同记号与对冲直觉，不是某家银行的限额政策。生产系统要把模型 Vega 转成市场桶，把期货 Delta 转成交易合约规格，并记录微笑动态假设。没有这些，希腊字母只是 PDE 的偏导数，不能当对冲指令。</p><p><span class="marginnote">把组合「Delta 中性、Gamma 中性、Vega 中性」写成已无风险，忽略了交叉项、期限错配与对手方。中性是限额语言，不是套利定理。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Delta、Gamma、Vega 是价值对现货一阶、二阶与对隐含波动一阶；Hull 用它们组织期权风险账。</li><li>Delta 对冲用标的或期货；Gamma 与 Vega 必须用非线性工具，且通常不能同时用单一工具清零。</li><li>Gamma–Theta 在 Black–Scholes 里对消；波动率移动打破对消，需要 Vega 对冲。</li><li>对冲比依赖微笑动态（sticky strike / delta / 模型）；SABR 与局部波动率给出不同 Delta。</li><li>分桶 Vega 比单一标量 Vega 更接近交易坐标；方差互换权重不同于 ATM Vega。</li><li>出处：Hull, <em>Options, Futures, and Other Derivatives</em>；微笑对冲见 Hagan et al., 2002；方差条带见 Carr and Madan, 1998。</li></ul>',6))])}const k=r(p,[["render",g]]);export{A as __pageData,k as default};
